"""Validate draft incident-evidence records without third-party dependencies.

Usage: python -m src.incident_evidence.validate path/to/record.json

A valid record is structurally and semantically coherent; it is not thereby
true, representative, safe to publish, or endorsed by Halcyon Threshold.
"""
from __future__ import annotations

import argparse
import json
import re
import sys
from datetime import datetime
from pathlib import Path
from typing import Any, Iterable

SCHEMA_PATH = Path(__file__).resolve().parents[2] / "schema" / "incident-record.schema.json"
MISSING_REASONS = {
    "not_collected", "unavailable_in_source", "not_applicable", "withheld", "ambiguous"
}


def _is_type(value: Any, name: str) -> bool:
    checks = {
        "object": lambda x: isinstance(x, dict),
        "array": lambda x: isinstance(x, list),
        "string": lambda x: isinstance(x, str),
        "boolean": lambda x: isinstance(x, bool),
        "null": lambda x: x is None,
        "number": lambda x: isinstance(x, (int, float)) and not isinstance(x, bool),
        "integer": lambda x: isinstance(x, int) and not isinstance(x, bool),
    }
    return checks[name](value)


def _walk_schema(value: Any, schema: dict[str, Any], path: str, errors: list[str]) -> None:
    """Small validator for the JSON-Schema subset used by this project."""
    if "const" in schema and value != schema["const"]:
        errors.append(f"{path}: expected constant {schema['const']!r}")
    if "enum" in schema and value not in schema["enum"]:
        errors.append(f"{path}: {value!r} is not an allowed value")

    expected = schema.get("type")
    if expected is not None:
        names = expected if isinstance(expected, list) else [expected]
        if not any(_is_type(value, name) for name in names):
            errors.append(f"{path}: expected type {' or '.join(names)}")
            return

    if isinstance(value, str):
        if "minLength" in schema and len(value) < schema["minLength"]:
            errors.append(f"{path}: shorter than {schema['minLength']} characters")
        if "maxLength" in schema and len(value) > schema["maxLength"]:
            errors.append(f"{path}: longer than {schema['maxLength']} characters")
        if "pattern" in schema and re.search(schema["pattern"], value) is None:
            errors.append(f"{path}: does not match required pattern")
        if schema.get("format") in {"date", "date-time"}:
            try:
                if schema["format"] == "date":
                    datetime.strptime(value, "%Y-%m-%d")
                else:
                    datetime.fromisoformat(value.replace("Z", "+00:00"))
            except ValueError:
                errors.append(f"{path}: invalid {schema['format']}")

    if isinstance(value, list):
        if schema.get("uniqueItems") and len({json.dumps(x, sort_keys=True) for x in value}) != len(value):
            errors.append(f"{path}: items must be unique")
        item_schema = schema.get("items")
        if item_schema:
            for index, item in enumerate(value):
                _walk_schema(item, item_schema, f"{path}[{index}]", errors)

    if isinstance(value, dict):
        for key in schema.get("required", []):
            if key not in value:
                errors.append(f"{path}.{key}: required property is missing")
        properties = schema.get("properties", {})
        additional = schema.get("additionalProperties", True)
        if additional is False:
            for key in value:
                if key not in properties:
                    errors.append(f"{path}.{key}: unexpected property")
        for key, item in value.items():
            child_path = f"{path}.{key}"
            if key in properties:
                _walk_schema(item, properties[key], child_path, errors)
            elif isinstance(additional, dict):
                _walk_schema(item, additional, child_path, errors)


def _at_path(record: Any, path: str) -> tuple[bool, Any]:
    """Resolve dotted paths with numeric array indices in square brackets."""
    current = record
    for part in path.split("."):
        match = re.fullmatch(r"([^\[]+)((?:\[\d+\])*)", part)
        if not match or not isinstance(current, dict) or match.group(1) not in current:
            return False, None
        current = current[match.group(1)]
        for raw_index in re.findall(r"\[(\d+)\]", match.group(2)):
            index = int(raw_index)
            if not isinstance(current, list) or index >= len(current):
                return False, None
            current = current[index]
    return True, current


def _missing_values(value: Any, path: str = "") -> Iterable[str]:
    if value is None or value == "unknown":
        yield path
    elif isinstance(value, dict):
        for key, item in value.items():
            child = f"{path}.{key}" if path else key
            yield from _missing_values(item, child)
    elif isinstance(value, list):
        for index, item in enumerate(value):
            yield from _missing_values(item, f"{path}[{index}]")


def _timestamp(value: Any) -> datetime | None:
    if not isinstance(value, str):
        return None
    try:
        return datetime.fromisoformat(value.replace("Z", "+00:00"))
    except ValueError:
        return None


def semantic_errors(record: dict[str, Any]) -> list[str]:
    errors: list[str] = []
    origin = record.get("source_origin")
    tier = record.get("evidence_tier")
    sources = record.get("sources")
    review = record.get("review", {})
    event = record.get("event", {})
    assessment = record.get("assessment", {})
    comparison = record.get("include_in_comparison")

    if origin == "synthetic":
        if sources != []:
            errors.append("sources: synthetic records must not list empirical sources")
        if tier != "S":
            errors.append("evidence_tier: synthetic records must use S")
        if review.get("permission_check") != "not_required_synthetic":
            errors.append("review.permission_check: synthetic records require not_required_synthetic")
        if comparison is not False:
            errors.append("include_in_comparison: synthetic records are never empirical comparisons")
    elif origin in {"public_source", "permissioned"}:
        if not isinstance(sources, list) or not sources:
            errors.append("sources: non-synthetic records require at least one source")
        if tier == "S":
            errors.append("evidence_tier: non-synthetic records cannot use S")
    if origin == "permissioned" and comparison and review.get("permission_check") != "permission_documented":
        errors.append("review.permission_check: comparison of permissioned data requires documented permission")
    if origin == "public_source" and comparison and review.get("permission_check") != "public_terms_reviewed":
        errors.append("review.permission_check: comparison of public data requires terms review")

    event_class = event.get("event_class")
    setting = event.get("setting")
    if event_class == "evaluation_finding" and setting != "evaluation":
        errors.append("event.setting: evaluation_finding requires evaluation setting")
    if event_class in {"observed_incident", "near_miss"} and setting not in {"deployment", "mixed"}:
        errors.append("event.setting: observed incidents and near misses require deployment or mixed setting")
    if event_class == "non_event" and comparison:
        errors.append("include_in_comparison: non-events are eligibility outcomes, not incident comparisons")
    if tier == "U" and comparison:
        errors.append("include_in_comparison: U-tier records are candidate notes only")

    observed = assessment.get("observed_harm")
    harms = assessment.get("harm_categories")
    if observed == "observed":
        if not isinstance(harms, list) or not harms:
            errors.append("assessment.harm_categories: observed harm requires at least one category")
    elif isinstance(harms, list) and harms:
        errors.append("assessment.harm_categories: must be empty unless harm was observed")

    safeguard_status = record.get("safeguards_assessment")
    safeguards = record.get("safeguards")
    if safeguard_status == "some_recorded":
        if not isinstance(safeguards, list) or not safeguards:
            errors.append("safeguards: some_recorded requires at least one safeguard")
    elif isinstance(safeguards, list) and safeguards:
        errors.append("safeguards: must be empty unless safeguards_assessment is some_recorded")

    start = _timestamp(event.get("timeframe_start"))
    end = _timestamp(event.get("timeframe_end"))
    detected = _timestamp(record.get("timeline", {}).get("detected_at"))
    contained = _timestamp(record.get("timeline", {}).get("contained_at"))
    if start and end and end < start:
        errors.append("event.timeframe_end: must not precede timeframe_start")
    if start and detected and detected < start:
        errors.append("timeline.detected_at: must not precede event start")
    if detected and contained and contained < detected:
        errors.append("timeline.contained_at: must not precede detection")

    missingness = record.get("missingness", {})
    expected_missing = set(_missing_values(record)) if isinstance(missingness, dict) else set()
    if isinstance(missingness, dict):
        for path, reason in missingness.items():
            exists, value = _at_path(record, path)
            if not exists:
                errors.append(f"missingness.{path}: path does not exist")
            elif value is not None and value != "unknown":
                errors.append(f"missingness.{path}: target is neither null nor unknown")
            if reason not in MISSING_REASONS:
                errors.append(f"missingness.{path}: invalid reason")
        for path in sorted(expected_missing - set(missingness)):
            errors.append(f"missingness.{path}: null/unknown value lacks a missingness reason")

    distribution = review.get("distribution")
    review_status = review.get("review_status")
    if distribution == "public":
        if review_status != "approved_public":
            errors.append("review.review_status: public distribution requires approved_public")
        if review.get("personal_data_check") is not True or review.get("hazardous_detail_check") is not True:
            errors.append("review: public distribution requires completed privacy and hazard checks")
        if review.get("permission_check") not in {"public_terms_reviewed", "permission_documented", "not_required_synthetic"}:
            errors.append("review.permission_check: public distribution permission is not established")
    if review_status == "approved_public" and distribution != "public":
        errors.append("review.distribution: approved_public must use public distribution")
    if comparison:
        if review_status not in {"approved_private", "approved_public"}:
            errors.append("include_in_comparison: review must be approved before comparison")
        if review.get("personal_data_check") is not True or review.get("hazardous_detail_check") is not True:
            errors.append("include_in_comparison: privacy and hazard checks must be complete")

    return errors


def validate_record(record: Any, schema: dict[str, Any] | None = None) -> list[str]:
    if schema is None:
        schema = json.loads(SCHEMA_PATH.read_text(encoding="utf-8"))
    errors: list[str] = []
    _walk_schema(record, schema, "record", errors)
    if isinstance(record, dict):
        errors.extend(semantic_errors(record))
    return errors


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("records", nargs="+", type=Path)
    args = parser.parse_args(argv)
    failed = False
    for path in args.records:
        try:
            record = json.loads(path.read_text(encoding="utf-8"))
            errors = validate_record(record)
        except (OSError, json.JSONDecodeError) as exc:
            print(f"FAIL {path}: {exc}")
            failed = True
            continue
        if errors:
            failed = True
            print(f"FAIL {path}")
            for error in errors:
                print(f"  - {error}")
        else:
            print(f"PASS {path}")
    return 1 if failed else 0


if __name__ == "__main__":
    sys.exit(main())

